<script setup>
import {ref,computed,onMounted,watch} from 'vue';import {clientLedger} from '../../shared/ledger.js';import {useRouter} from 'vue-router';import {api,mutate,notify,ui} from '../lib/api.js';import {money,dateLabel,paid,progress,sizeLabel,today} from '../lib/format.js';import {labels,lineSchema} from '../../shared/contracts.js';import {lineTotal} from '../../shared/money.js';import PageTitle from '../components/PageTitle.vue';import Icon from '../components/Icon.vue';import Badge from '../components/Badge.vue';import CrudForm from '../components/CrudForm.vue';import EmptyState from '../components/EmptyState.vue';import Modal from '../components/Modal.vue';
const props=defineProps({type:String,id:String});const router=useRouter(),record=ref(null),error=ref(''),tab=ref('overview'),open=ref(false),formKind=ref(''),editing=ref(null),context=ref({}),busy=ref(false),notes=ref(''),task=ref(''),confirm=ref(null),project=ref({}),abbyBusy=ref(false),confirmAbby=ref(false);
const abbyFinalized=computed(()=>!!record.value?.abbyStatus&&record.value.abbyStatus!=='draft');
const quoteEditable=computed(()=>props.type==='quotes'&&['draft','sent','viewed','accepted','declined','expired'].includes(record.value?.status)&&!record.value?.invoiceLock);
const quoteEditNote=computed(()=>{if(props.type!=='quotes'||!record.value)return '';if(record.value.invoiceLock)return 'Ce devis a donné lieu à une facture officielle : il ne peut plus être modifié.';if(record.value.status!=='draft')return `Ce devis est déjà ${(labels[record.value.status]||record.value.status).toLowerCase()}. Vous pouvez le modifier ; vos changements ne régénèrent pas une facture déjà créée.`;if(record.value.invoiceDraftPending)return 'Une facture brouillon existe pour ce devis ; vos modifications ne la mettent pas à jour automatiquement.';return '';});
const title=computed(()=>record.value?.name||record.value?.title||record.value?.supplier||'');
const tabs=computed(()=>({clients:[['overview','Vue d’ensemble'],['projects','Projets'],['quotes','Devis'],['invoices','Factures'],['payments','Paiements'],['documents','Documents'],['notes','Notes'],['history','Historique']],quotes:[['overview','Vue d’ensemble'],['items','Prestations'],['documents','Documents'],['history','Historique']],projects:[['overview','Vue d’ensemble'],['items','Prestations'],['payments','Paiements'],['invoices','Factures'],['documents','Documents'],['notes','Notes'],['history','Historique']],invoices:[['overview','Vue d’ensemble'],['items','Prestations'],['payments','Paiements'],['documents','Documents'],['history','Historique']],expenses:[['overview','Vue d’ensemble'],['documents','Documents']]}[props.type]));
const total=computed(()=>props.type==='clients'?record.value?clientLedger(record.value).totalCents:0:record.value?.totalCents||0);
const transitions=computed(()=>({draft:['sent'],sent:['viewed','accepted','declined'],viewed:['accepted','declined'],accepted:[],declined:[],expired:[]}[record.value?.status]||[]));
async function load(){try{error.value='';record.value=await api(`/${props.type}/${props.id}`);notes.value=record.value.notes||'';project.value={title:record.value.title,startDate:record.value.startDate,dueDate:record.value.dueDate};}catch(e){error.value=e.message;}}
onMounted(load);watch(()=>ui.revision,load);
function showForm(kind,edit=false){formKind.value=kind;editing.value=edit?record.value:null;context.value=kind==='documents'?{[props.type==='clients'?'clientId':props.type==='quotes'?'quoteId':props.type==='projects'?'projectId':props.type==='invoices'?'invoiceId':'expenseId']:props.id}:{clientId:props.type==='clients'?props.id:record.value.clientId,projectId:props.type==='projects'?props.id:record.value.projectId,invoiceId:props.type==='invoices'?props.id:undefined,amountCents:Math.max(0,total.value-paid(record.value))};open.value=true;}
async function statusChange(status){busy.value=true;try{await mutate(`/${props.type}/${props.id}${props.type==='projects'?'':'/status'}`,'PATCH',{status},'Statut mis à jour.');}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
async function convert(){busy.value=true;try{const p=await mutate(`/quotes/${props.id}/convert`,'POST',{},'Projet créé.');router.push('/projects/'+p.id);}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
async function duplicate(){busy.value=true;try{const q=await mutate(`/quotes/${props.id}/duplicate`,'POST',{},'Devis dupliqué.');router.push('/quotes/'+q.id+'/edit');}catch(e){notify(e.message,'error');}finally{busy.value=false;}}
async function saveNotes(){try{await mutate(`/${props.type}/${props.id}`,'PATCH',props.type==='clients'?{...record.value,notes:notes.value}:{notes:notes.value},'Notes enregistrées.');}catch(e){notify(e.message,'error');}}
async function saveProject(){try{await mutate(`/projects/${props.id}`,'PATCH',project.value,'Projet mis à jour.');}catch(e){notify(e.message,'error');}}
async function addTask(){if(!task.value.trim())return;try{await mutate(`/projects/${props.id}/tasks`,'POST',{title:task.value});task.value='';}catch(e){notify(e.message,'error');}}
async function toggleTask(t,event){try{await mutate('/tasks/'+t.id,'PATCH',{done:event.target.checked},'Checklist mise à jour.');}catch(e){event.target.checked=t.done;notify(e.message,'error');}}
async function remove(){try{await mutate(`/${confirm.value.type}/${confirm.value.id}`,'DELETE',undefined,'Élément supprimé.');confirm.value=null;}catch(e){notify(e.message,'error');}}
async function allocate(id){try{await mutate('/payments/'+id+'/allocate','POST',{invoiceId:props.id},'Paiement affecté sans nouvel encaissement.');}catch(e){notify(e.message,'error');}}
async function archive(){try{await mutate('/clients/'+props.id,'PATCH',{...record.value,status:record.value.status==='archived'?'active':'archived'});}catch(e){notify(e.message,'error');}}
async function createAbbyInvoice(){abbyBusy.value=true;try{const inv=await mutate(`/quotes/${props.id}/abby-invoice`,'POST',{},'Facture Abby créée.');router.push('/invoices/'+inv.id);}catch(e){notify(e.message,'error');}finally{abbyBusy.value=false;}}
async function finalizeAbby(){abbyBusy.value=true;try{await mutate(`/invoices/${props.id}/abby/finalize`,'POST',{},'Facture finalisée chez Abby.');confirmAbby.value=false;}catch(e){notify(e.message,'error');}finally{abbyBusy.value=false;}}
async function syncAbby(){abbyBusy.value=true;try{await mutate(`/invoices/${props.id}/abby/sync`,'POST',{},'Statut Abby synchronisé.');}catch(e){notify(e.message,'error');}finally{abbyBusy.value=false;}}
const referenceTitle=computed(()=>record.value?.reference||'Dossier client');
function statusOf(r){if(r.payments&&r.dueDate&&['sent','partial','overdue','paid'].includes(r.status))return paid(r)>=r.totalCents?'paid':r.dueDate<today()?'overdue':paid(r)?'partial':'sent';return r.status;}
</script>
<template><RouterLink :to="'/'+type" class="back-link"><Icon name="ArrowLeft" :size="15"/>Retour à la liste</RouterLink><p v-if="error" class="form-error">{{error}} <button @click="load">Réessayer</button></p><div v-if="!record&&!error" class="skeleton-page"></div><template v-if="record"><PageTitle :number="referenceTitle" :title="title.toUpperCase()" :subtitle="record.client?.name||record.email||record.category"><template v-if="['quotes','invoices'].includes(type)"><a class="btn" :href="`/api/${type}/${id}/pdf`" target="_blank" rel="noopener"><Icon name="Download"/>PDF / Imprimer</a><RouterLink v-if="(type==='invoices'&&record.status==='draft')||quoteEditable" class="btn" :to="`/${type}/${id}/edit`"><Icon name="Pencil"/>Modifier</RouterLink><button v-if="type==='quotes'" class="btn" @click="duplicate" :disabled="busy"><Icon name="Copy"/>Dupliquer</button><button v-if="type==='quotes'&&record.status==='accepted'" class="btn" :disabled="abbyBusy" @click="createAbbyInvoice"><Icon name="Receipt"/>Créer la facture (Abby)</button><button v-if="type==='quotes'&&record.status==='accepted'&&!record.project" class="btn primary" @click="convert" :disabled="busy">Créer le projet<Icon name="ArrowUpRight"/></button><RouterLink v-if="record.project&&type==='quotes'" class="btn primary" :to="'/projects/'+record.project.id">Ouvrir le projet<Icon name="ArrowUpRight"/></RouterLink><button v-if="type==='invoices'&&!['draft','cancelled','paid'].includes(record.status)" class="btn primary" @click="showForm('payments')"><Icon name="Plus"/>Enregistrer un paiement</button></template><template v-else-if="type==='projects'"><RouterLink class="btn" :to="'/invoices/new?project='+id"><Icon name="Receipt"/>Créer une facture</RouterLink><button class="btn primary" @click="showForm('payments')"><Icon name="Plus"/>Paiement</button></template><template v-else-if="type==='clients'"><button class="btn" @click="showForm('clients',true)">Modifier</button><RouterLink class="btn primary" :to="'/quotes/new?client='+id"><Icon name="Plus"/>Créer un devis</RouterLink></template><button v-else class="btn primary" @click="showForm('expenses',true)">Modifier la dépense</button></PageTitle>
<div class="row-between" style="margin-bottom:22px"><Badge v-if="record.status" :status="record.status"/><Badge v-else :status="record.paid?'paid':'pending'"/><div class="row-between"><select v-if="type==='projects'" :value="record.status" :disabled="busy" @change="statusChange($event.target.value)" aria-label="Statut du projet"><option v-for="s in ['pending','waiting','progress','review','changes','completed','delivered','archived']" :key="s" :value="s">{{labels[s]}}</option></select><template v-if="type==='quotes'"><button v-for="s in transitions" :key="s" class="btn small" :disabled="busy" @click="statusChange(s)">{{s==='sent'?'Marquer envoyé':s==='viewed'?'Marquer vu':s==='accepted'?'Accepter':'Refuser'}}</button></template><template v-if="type==='invoices'&&record.status==='draft'"><button class="btn small primary" :disabled="busy" @click="statusChange('sent')">Émettre la facture</button><button class="text-button" :disabled="busy" @click="statusChange('cancelled')">Annuler le brouillon</button></template><button v-if="type==='clients'" class="text-button" @click="archive">{{record.status==='archived'?'Réactiver le client':'Archiver le client'}}</button></div></div>
<section class="metrics-strip"><div><small>{{type==='clients'?'TOTAL DES PROJETS':type==='expenses'?'MONTANT HT':'TOTAL TTC'}}</small><strong>{{money(type==='expenses'?record.netCents:total,true)}}</strong></div><div><small>{{type==='quotes'?'ACOMPTE':type==='expenses'?'TVA':'ENCAISSÉ'}}</small><strong>{{money(type==='quotes'?Math.round(total*record.depositBps/10000):type==='expenses'?record.totalCents-record.netCents:paid(record),true)}}</strong></div><div><small>{{type==='quotes'?'RÉCURRENT / MOIS':type==='expenses'?'MONTANT TTC':'RESTE À PAYER'}}</small><strong class="accent">{{money(type==='quotes'?record.recurringCents:type==='expenses'?total:(type==='clients'?clientLedger(record).remainingCents:Math.max(0,total-paid(record))),true)}}</strong></div></section>
<section v-if="type==='invoices'&&record.abbyInvoiceId" class="detail-card" style="margin-bottom:22px"><div class="row-between"><h2 style="margin:0">FACTURATION ABBY.</h2><Badge v-if="record.abbyStatus" :status="record.abbyStatus"/></div><dl class="detail-fields" style="margin-top:14px"><div><dt>Numéro officiel</dt><dd>{{record.abbyNumber||'Brouillon — non finalisé'}}</dd></div><div><dt>Statut Abby</dt><dd>{{labels[record.abbyStatus]||record.abbyStatus||'—'}}</dd></div><div v-if="record.abbyTest!==null"><dt>Mode</dt><dd>{{record.abbyTest?'Test (document non légal)':'Réel'}}</dd></div><div v-if="record.lastSyncedAt"><dt>Dernière synchro</dt><dd>{{dateLabel(record.lastSyncedAt)}}</dd></div></dl><div class="row-between" style="margin-top:16px;gap:10px;flex-wrap:wrap"><a class="btn" :href="`/api/invoices/${id}/abby/pdf`" target="_blank" rel="noopener"><Icon name="Download"/>PDF Abby</a><button class="btn" :disabled="abbyBusy" @click="syncAbby"><Icon name="RefreshCw"/>Synchroniser</button><button v-if="!abbyFinalized" class="btn primary" :disabled="abbyBusy" @click="confirmAbby=true"><Icon name="ShieldCheck"/>Finaliser</button><span v-else class="section-note">Facture finalisée chez Abby : lecture seule.</span></div></section>
<p v-if="type==='quotes'&&quoteEditNote" class="section-note" style="margin-bottom:22px">{{quoteEditNote}}</p>
<nav class="tabs" aria-label="Sections du dossier"><button v-for="[key,label] in tabs" :key="key" :class="{selected:tab===key}" @click="tab=key">{{label}}<span v-if="Array.isArray(record[key])"> ({{record[key].length}})</span></button></nav>
<div v-if="tab==='overview'" class="detail-grid"><section class="detail-card"><h2>LE DOSSIER.</h2><dl class="detail-fields"><template v-if="type==='clients'"><div v-for="[label,key] in [['Contact','contact'],['Email','email'],['Téléphone','phone'],['Adresse','address'],['SIRET','siret']]" :key="key"><dt>{{label}}</dt><dd>{{record[key]||'Non renseigné'}}</dd></div><div><dt>Apporté par</dt><dd><RouterLink v-if="record.referrer" class="text-button" to="/apporteurs">{{record.referrer.name}}<Icon name="ArrowUpRight" :size="14"/></RouterLink><template v-else>Contact direct</template></dd></div></template><template v-else-if="type==='expenses'"><div v-for="[label,value] in [['Fournisseur',record.supplier],['Catégorie',record.category],['Date',dateLabel(record.date)],['Échéance',dateLabel(record.dueDate)],['Paiement',labels[record.method]],['Commentaire',record.comment||'—']]" :key="label"><dt>{{label}}</dt><dd>{{value}}</dd></div></template><template v-else><div><dt>Client</dt><dd><RouterLink :to="'/clients/'+record.clientId" class="text-button">{{record.client?.name}}<Icon name="ArrowUpRight" :size="14"/></RouterLink></dd></div><div><dt>Référence</dt><dd>{{record.reference}}</dd></div><div><dt>{{type==='projects'?'Commande':'Émission'}}</dt><dd>{{dateLabel(record.orderDate||record.issuedDate)}}</dd></div><div><dt>{{type==='quotes'?'Validité':'Échéance'}}</dt><dd>{{dateLabel(record.validUntil||record.dueDate)}}</dd></div><div v-if="record.quote"><dt>Devis d’origine</dt><dd><RouterLink class="text-button" :to="'/quotes/'+record.quote.id">{{record.quote.reference}}<Icon name="ArrowUpRight" :size="14"/></RouterLink></dd></div><div v-if="record.estimatedDelay"><dt>Délai estimé</dt><dd>{{record.estimatedDelay}}</dd></div><div v-if="record.conditions"><dt>Conditions de paiement</dt><dd>{{record.conditions}}</dd></div><div v-if="record.legalNotice"><dt>Mentions</dt><dd>{{record.legalNotice}}</dd></div><div v-if="record.proClient"><dt>Mentions B2B</dt><dd>Pénalités de retard et indemnité de 40 € imprimées.</dd></div><div v-if="type==='quotes'&&record.notes"><dt>Note projet</dt><dd><span style="white-space:pre-wrap">{{record.notes}}</span><br><small class="muted">{{record.notesOnPdf?'Affichée sur le devis (PDF).':'Interne — non imprimée sur le devis.'}}</small></dd></div></template></dl><form v-if="type==='projects'" @submit.prevent="saveProject" style="margin-top:24px"><label>Nom du projet<input v-model="project.title" required></label><div class="form-grid"><label>Démarrage<input v-model="project.startDate" type="date" required></label><label>Livraison estimée<input v-model="project.dueDate" type="date" required></label></div><button class="btn">Enregistrer les informations</button></form></section><section class="detail-card" v-if="type==='projects'"><div class="row-between" style="margin-bottom:16px"><h2 style="margin:0">PROCHAINE ÉTAPE.</h2><span class="mono accent">{{progress(record)}}%</span></div><ul class="checklist"><li v-for="t in record.tasks" :key="t.id"><label class="check-label" :class="{done:t.done}"><input type="checkbox" :checked="t.done" @change="toggleTask(t,$event)">{{t.title}}</label><button class="icon-button" @click="confirm={type:'tasks',id:t.id,name:t.title}" aria-label="Supprimer cette étape"><Icon name="X" :size="14"/></button></li></ul><form class="inline-form" @submit.prevent="addTask"><input v-model="task" placeholder="Ajouter une étape…" aria-label="Nom de l’étape" required><button class="btn" aria-label="Ajouter l’étape"><Icon name="Plus"/></button></form></section><section v-else class="detail-card"><h2>{{type==='clients'?'RELATION CLIENT.':'LES PRESTATIONS.'}}</h2><template v-if="type==='clients'"><p class="note-text">{{record.notes||'Ajoutez des notes internes pour garder le contexte de cette relation.'}}</p><div class="section-note" style="margin-top:24px">{{record.projects.length}} projets · {{record.quotes.length}} devis · {{record.invoices.length}} factures<template v-if="record.commissions?.length"> · {{record.commissions.length}} commission{{record.commissions.length>1?'s':''}} d’apport ({{money(record.commissions.reduce((n,c)=>n+c.amountCents,0),true)}})</template></div></template><template v-else-if="record.items"><div v-for="i in record.items" :key="i.id" class="document-row"><div><strong>{{i.name}}</strong><small>{{i.quantityMilli/1000}} × {{money(i.unitCents,true)}}{{i.frequency==='monthly'?' / mois':i.frequency==='yearly'?' / an':''}}</small></div><span class="mono">{{money(lineTotal(lineSchema.parse(i),record.discountBps).total,true)}}</span></div></template><template v-else><p>{{record.documents.length}} pièce{{record.documents.length>1?'s':''}} jointe{{record.documents.length>1?'s':''}}.</p><button class="btn" style="margin-top:20px" @click="tab='documents'"><Icon name="FolderOpen"/>Voir les documents</button></template></section></div>
<div v-else-if="tab==='items'" class="panel table-scroll"><table><thead><tr><th>SECTION / PRESTATION</th><th>QUANTITÉ</th><th>PRIX HT</th><th>REMISE</th><th>TVA</th><th>FRÉQUENCE</th><th>TOTAL TTC</th></tr></thead><tbody><tr v-for="i in record.items" :key="i.id"><td><strong>{{i.name}}</strong><div class="table-sub">{{i.section}} · {{i.category}}</div><div class="table-sub">{{i.description}}</div><span v-if="i.optional" class="badge">Option {{i.selected?'retenue':'non retenue'}}</span></td><td>{{i.quantityMilli/1000}}</td><td>{{money(i.unitCents,true)}}</td><td>{{i.discountBps/100}}%</td><td>{{i.vatBps/100}}%</td><td>{{labels[i.frequency]}}</td><td>{{money(lineTotal(lineSchema.parse(i),record.discountBps).total,true)}}</td></tr></tbody></table></div>
<template v-else-if="['projects','quotes','invoices'].includes(tab)"><div class="row-between" style="margin-bottom:20px"><h2>{{tabs.find(t=>t[0]===tab)?.[1].toUpperCase()}}</h2><RouterLink v-if="tab==='invoices'&&type==='projects'" class="btn" :to="'/invoices/new?project='+id"><Icon name="Plus"/>Créer une facture</RouterLink></div><div v-if="record[tab]?.length" class="panel table-scroll"><table><thead><tr><th>RÉFÉRENCE</th><th>OBJET</th><th>STATUT</th><th>TOTAL</th><th></th></tr></thead><tbody><tr v-for="r in record[tab]" :key="r.id"><td class="mono">{{r.reference}}</td><td>{{r.title}}</td><td><Badge :status="statusOf(r)"/></td><td>{{money(r.totalCents,true)}}</td><td><RouterLink :to="`/${tab}/${r.id}`" class="icon-button" aria-label="Ouvrir le dossier"><Icon name="ArrowUpRight"/></RouterLink></td></tr></tbody></table></div><EmptyState v-else title="Aucun document pour le moment." description="Les documents associés apparaîtront ici."/></template>
<template v-else-if="tab==='payments'"><div class="row-between" style="margin-bottom:20px"><h2>LES ENCAISSEMENTS.</h2><button v-if="type!=='invoices'||!['draft','cancelled','paid'].includes(record.status)" class="btn primary" @click="showForm('payments')"><Icon name="Plus"/>Enregistrer un paiement</button></div><div v-if="type==='invoices'&&record.project?.payments?.length&&!['draft','cancelled','paid'].includes(record.status)" class="section-note" style="margin-bottom:20px"><p>Des paiements reçus sur ce projet peuvent être affectés à cette facture.</p><div v-for="p in record.project.payments" :key="p.id" class="row-between" style="margin-top:10px"><span>{{money(p.amountCents,true)}} · {{dateLabel(p.date,true)}} · {{p.reference||'Paiement projet'}}</span><button class="text-button" @click="allocate(p.id)">Affecter à cette facture<Icon name="Link" :size="14"/></button></div></div><div v-if="record.payments?.length" class="panel table-scroll"><table><thead><tr><th>DATE</th><th>MONTANT</th><th>MODE</th><th>RÉFÉRENCE</th><th>COMMENTAIRE</th></tr></thead><tbody><tr v-for="p in record.payments" :key="p.id"><td>{{dateLabel(p.date)}}</td><td class="mono">{{money(p.amountCents,true)}}</td><td>{{labels[p.method]}}</td><td>{{p.reference||'—'}}</td><td>{{p.comment||'—'}}</td></tr></tbody></table></div><EmptyState v-else title="Aucun paiement enregistré." description="Enregistrez un encaissement pour mettre à jour le solde."/></template>
<template v-else-if="tab==='documents'"><div class="row-between" style="margin-bottom:20px"><h2>LES DOCUMENTS.</h2><button class="btn primary" @click="showForm('documents')"><Icon name="Upload"/>Ajouter un document</button></div><div v-for="d in record.documents" :key="d.id" class="document-row"><Icon name="FileText"/><div><strong>{{d.name}}</strong><small>{{sizeLabel(d.size)}} · {{dateLabel(d.createdAt)}}</small></div><a class="icon-button" :href="`/api/documents/${d.id}/download`" aria-label="Télécharger"><Icon name="Download"/></a><button class="icon-button" aria-label="Supprimer" @click="confirm={type:'documents',id:d.id,name:d.name}"><Icon name="Trash2"/></button></div><EmptyState v-if="!record.documents?.length" title="Un dossier bien rangé commence ici." description="Ajoutez contrats, justificatifs, maquettes et documents utiles."/></template>
<form v-else-if="tab==='notes'" @submit.prevent="saveNotes"><label>Notes internes<textarea v-model="notes" rows="12" placeholder="Contexte, décisions, points à retenir…"/></label><div><button class="btn primary">Enregistrer les notes<Icon name="Check"/></button></div></form>
<section v-else-if="tab==='history'" class="detail-card"><h2>L’HISTORIQUE DU DOSSIER.</h2><ol class="activity-list" style="padding-left:0"><li v-for="a in record.activities" :key="a.id"><i></i><div>{{a.action}}<small>{{dateLabel(a.createdAt)}} · {{new Date(a.createdAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}}</small></div></li></ol><p v-if="!record.activities?.length" class="muted">Aucune action enregistrée.</p></section>
<CrudForm :open="open" :kind="formKind" :record="editing" :context="context" @close="open=false" @saved="load"/><Modal :open="!!confirm" title="SUPPRIMER CET ÉLÉMENT ?" @close="confirm=null"><p>« {{confirm?.name}} » sera supprimé. Cette action est définitive.</p><div class="form-actions"><button class="btn" @click="confirm=null">Conserver</button><button class="btn danger" @click="remove">Supprimer</button></div></Modal><Modal :open="confirmAbby" title="FINALISER CETTE FACTURE ?" @close="confirmAbby=false"><p>Une fois finalisée, un numéro officiel sera attribué et elle ne pourra plus être modifiée. Confirmer ?</p><div class="form-actions"><button class="btn" @click="confirmAbby=false">Annuler</button><button class="btn primary" :disabled="abbyBusy" @click="finalizeAbby">Finaliser</button></div></Modal></template></template>
